def count_squares(lines):
    """
    Counts the number of squares in an ASCII art picture.

    Args:
    lines (List[str]): An array of strings representing the ASCII art picture.

    Returns:
    int: The number of squares in the picture.
    """
    height = len(lines)
    if height == 0:
        return 0

    width = len(lines[0])
    if width == 0:
        return 0

    def is_corner(x, y):
        """Check if the given position is a corner."""
        return lines[y][x] == '+'

    def is_horizontal(x, y):
        """Check if the given position is part of a horizontal line."""
        return lines[y][x] == '-'

    def is_vertical(x, y):
        """Check if the given position is part of a vertical line."""
        return lines[y][x] == '|'

    def is_square(x, y, size):
        """Check if there is a square starting at (x, y) with the given size."""
        for i in range(size):
            for j in range(size):
                if not (is_corner(x + i, y + j) and
                        is_corner(x + i, y + j + 1) and
                        is_corner(x + i + 1, y + j) and
                        is_corner(x + i + 1, y + j + 1)):
                    return False
                if i > 0 and not (is_horizontal(x + i, y + j) and is_horizontal(x + i, y + j + 1)):
                    return False
                if j > 0 and not (is_vertical(x + i, y + j) and is_vertical(x + i + 1, y + j)):
                    return False
        return True

    count = 0
    for size in range(2, min(height, width) + 1):
        for y in range(height - size + 1):
            for x in range(width - size + 1):
                if is_square(x, y, size):
                    count += 1

    return count
